export const defaultWheel=(index=0)=>({name:['Front Left','Front Right','Rear Left','Rear Right'][index]||'Wheel '+(index+1),position:[index%2? .9:-.9,.1,index<2?1.25:-1.25],radius:.38,width:.24,restLength:.35,travel:.25,stiffness:30,compression:4.4,relaxation:2.3,maxForce:100000,friction:1.5,sideFriction:1,steer:index<2?1:0,drive:true,brake:true,handbrake:index>=2});
export const wheelNumbers={radius:[.01,100],width:[.01,100],restLength:[.001,100],travel:[0,100],stiffness:[0,1000000],compression:[0,1000000],relaxation:[0,1000000],maxForce:[0,10000000],friction:[0,10000],sideFriction:[0,10000],steer:[-1,1]};
export function validVehicleWheels(wheels){return Array.isArray(wheels)&&wheels.length>=1&&wheels.length<=256&&wheels.every(w=>w&&Object.keys(w).every(k=>['name','position','drive','brake','handbrake',...Object.keys(wheelNumbers)].includes(k))&&typeof w.name==='string'&&w.name.length>0&&w.name.length<=80&&Array.isArray(w.position)&&w.position.length===3&&w.position.every(v=>Number.isFinite(v)&&Math.abs(v)<=10000)&&Object.entries(wheelNumbers).every(([key,[min,max]])=>Number.isFinite(w[key])&&w[key]>=min&&w[key]<=max)&&['drive','brake','handbrake'].every(k=>typeof w[k]==='boolean'));}
export function validVehicleInput(throttle,steering,brake,handbrake){return [throttle,steering,brake,handbrake].every(Number.isFinite)&&Math.abs(throttle)<=1&&Math.abs(steering)<=1&&brake>=0&&brake<=1&&handbrake>=0&&handbrake<=1;}
export function editVehicleWheel(wheels,input){const next=structuredClone(wheels),w=next[Number(input.dataset.wheelIndex)];if(!w)throw Error('휠을 찾을 수 없어요.');if(input.dataset.wheelAxis!==undefined)w.position[Number(input.dataset.wheelAxis)]=Number(input.value);else w[input.dataset.wheelKey]=input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value;return next;}
